#define CGLTF_IMPLEMENTATION
#include "cgltf.h"
#define BATTLEFIELD_SAMPLE_LIBRARY
#include "battlefield_world_sample.cpp"
#include "engine/world_scenery.cpp"
#include <map>
#include <cassert>
int main(int argc,char**argv){const bool query=argc==4;const double query_x=query?std::stod(argv[1]):-12018,query_z=query?std::stod(argv[2]):5164;const float query_y=query?std::stof(argv[3]):12;assert(initialize_world()==0);std::ifstream doc("world.studio");std::string line;std::vector<std::array<std::string,2>> names;std::vector<WorldSceneryDefinition> definitions;while(std::getline(doc,line)){std::istringstream f(line);std::string k;f>>k;if(k!="asset")continue;std::array<std::string,2> n;WorldSceneryDefinition d;f>>n[0]>>n[1]>>d.lods>>d.collision>>d.vegetation>>d.distance>>d.split;names.push_back(n);definitions.push_back(d);}for(size_t i=0;i<definitions.size();i++){definitions[i].name=names[i][0].c_str();definitions[i].stem=names[i][1].c_str();}char e[256];assert(world_scenery_configure(definitions.data(),definitions.size(),e,sizeof e));auto *scene=new WorldScenery;std::map<unsigned,Group> groups;std::vector<std::string> labels;
 for(const auto &file:std::filesystem::directory_iterator("scenery")){if(file.path().extension()!=".txt")continue;std::ifstream in(file.path());unsigned lineno=0;while(std::getline(in,line)){++lineno;std::istringstream f(line);std::string name;if(!(f>>name)||name[0]=='#')continue;double u,v,deg,scale,burial;if(!(f>>u>>v>>deg>>scale>>burial))return 2;const auto it=std::find_if(aliases.begin(),aliases.end(),[&](const Alias&a){return name==a.name;});if(it==aliases.end())continue;unsigned id=it-aliases.begin();Placement p;p.alias=id;world_atlas_uv_to_world(u,v,&p.x,&p.z);if(std::hypot(p.x-query_x,p.z-query_z)>45||it->collision==Collision::None)continue;std::vector<double> extra;std::string token;while(f>>token){if(token=="wind")break;extra.push_back(std::stod(token));}p.y=world_atlas_height(p.x,p.z)-burial;p.scale=scale;p.burial=burial;p.yaw=deg*pi/180;if(extra.size()>=1)p.elevation=extra[0];if(extra.size()>=2)p.offset_y=extra[1];if(extra.size()>=7){p.pitch=extra[2]*pi/180;p.roll=extra[3]*pi/180;p.sx=extra[4];p.sy=extra[5];p.sz=extra[6];}if(extra.size()==8)p.pivot_y=extra[7];if(!groups.count(id)){Group g;g.alias=id;world_model_cpu::Options options;world_model_cpu::Bounds b;std::string error,path="models/"+std::string(it->stem)+((it->tree||it->named_near_file)?"_near.glb":".glb");if(!world_model_cpu::bounds_only(path.c_str(),options,b,error)){std::cerr<<path<<' '<<error<<'\n';return 3;}std::copy(b.minimum,b.minimum+3,g.minimum);std::copy(b.maximum,b.maximum+3,g.maximum);groups[id]=g;}auto &g=groups.at(id);if(rigid(id))p.y=supported_height(p,g);p.y+=p.elevation+p.offset_y;if(std::isfinite(p.pivot_y))p.y=p.pivot_y;size_t before=scene->colliders.size();placement_colliders(scene->colliders,p,g);for(size_t i=before;i<scene->colliders.size();i++)scene->colliders[i].record=scene->placements.size();scene->placements.push_back(p);labels.push_back(file.path().filename().string()+":"+std::to_string(lineno)+" "+name);}}
 if(query){auto *probe=new WorldScenery;const double dxs[8]={1,1,0,-1,-1,-1,0,1},dzs[8]={0,1,1,1,0,-1,-1,-1};for(unsigned d=0;d<8;d++){double length=std::hypot(dxs[d],dzs[d]),x=query_x+dxs[d]/length,z=query_z+dzs[d]/length;std::cout<<"direction "<<dxs[d]<<','<<dzs[d]<<" safe="<<world_scenery_can_move(scene,query_x,query_z,x,z,query_y,1.75,.32);for(const auto&c:scene->colliders){probe->colliders.clear();probe->colliders.push_back(c);if(!world_scenery_can_move(probe,query_x,query_z,x,z,query_y,1.75,.32))std::cout<<" BLOCKER "<<labels[c.record]<<" bounds "<<c.min_x<<','<<c.max_x<<','<<c.min_z<<','<<c.max_z;}std::cout<<'\n';}return 0;}
 unsigned checked=0,failures=0;const double side_x=-8/std::hypot(20.,8.),side_z=20/std::hypot(20.,8.);for(unsigned direction=0;direction<2;direction++)for(double lane:{-.70,0.,.70}){double px=0,pz=0;for(unsigned k=0;k<=220;k++){double t=.025+.95*k/220;if(direction)t=1-t;double x=-12028+20*t+side_x*lane,z=5160+8*t+side_z*lane;float feet=12.0+.15*t;bool ok=world_scenery_can_move(scene,k?px:x,k?pz:z,x,z,feet,1.75,.32);++checked;if(!ok){++failures;if(failures<12){std::cerr<<"blocked "<<x<<' '<<z<<" lane "<<lane<<" by";for(const auto&c:scene->colliders){auto *probe=new WorldScenery;probe->colliders.push_back(c);if(!world_scenery_can_move(probe,k?px:x,k?pz:z,x,z,feet,1.75,.32))std::cerr<<' '<<labels[c.record];}std::cerr<<'\n';}}px=x;pz=z;}}
 std::cout<<"Bridge scenery sweep: "<<checked<<" three-lane bidirectional capsule samples, "<<scene->placements.size()<<" actual scene placements, "<<scene->colliders.size()<<" production colliders, "<<failures<<" failures\n";world_atlas_shutdown();return failures?4:0;}
